#!/usr/bin/env bash
set -euo pipefail

# Tower Defense Android-ready project installer.
# Run this from the root of the empty GitHub repository.

ROOT="$(pwd)"
TMP="$(mktemp -d)"
cleanup() { rm -rf "$TMP"; }
trap cleanup EXIT

ARCHIVE="$TMP/tower-defense.zip"

cat > "$ARCHIVE.b64" <<'BASE64'

BASE64
base64 -d "$ARCHIVE.b64" > "$ARCHIVE"
unzip -q "$ARCHIVE" -d "$TMP/extracted"

SRC="$TMP/extracted/tower-defense-source"
if [ ! -d "$SRC" ]; then
  echo "ERROR: project archive structure was not found."
  exit 1
fi

# Copy the project into the repository root, including hidden files.
cp -a "$SRC/." "$ROOT/"

# Don't leave the installer in the repository.
rm -f "$ROOT/install-tower-defense.sh"

# Remove any accidental generated dependency folders if present.
rm -rf "$ROOT/node_modules"

echo
echo "=============================================="
echo " Tower Defense Android project installed!"
echo "=============================================="
echo
echo "Next commands:"
echo "  git add ."
echo '  git commit -m "Add Tower Defense Android project"'
echo "  git push"
echo
echo "Then open GitHub -> Actions -> Build Android APK."
echo
